<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <title>Maze Bot Discovery</title>
    <style>
        body { 
            background: #1a1a1a; 
            color: #eee; 
            font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif; 
            display: flex; 
            flex-direction: column; 
            align-items: center; 
            justify-content: center; 
            height: 100vh; 
            margin: 0; 
            overflow: hidden; 
        }
        #ui { margin-bottom: 15px; text-align: center; }
        #maze { border: 4px solid #444; box-shadow: 0 0 20px rgba(0,0,0,0.5); line-height: 0; }
        button { 
            background: #4a90e2; 
            color: white; 
            border: none; 
            padding: 10px 25px; 
            border-radius: 5px; 
            font-size: 16px; 
            cursor: pointer; 
            transition: background 0.2s; 
            margin-top: 15px; 
        }
        button:hover { background: #357abd; }
        .stats { font-size: 20px; font-weight: bold; }
    </style>
</head>
<body>
    <div id="ui">
        <div class="stats">Completed: <span id="completed">0</span> | Time: <span id="timer">0</span></div>
        <button id="reset">Reset Maze</button>
    </div>
    <div id="maze">
        <canvas id="gameCanvas"></canvas>
    </div>

    <script>
        const ROWS = 21;
        const COLS = 21;
        const BOT_COUNT = 24;

        /** Simple LCG-based random number generator for deterministic behavior */
        function mulberry32(a) {
            return function() {
                let t = a += 0x6D2B79F5;
                t = Math.imul(t ^ t >>> 15, t | 1);
                t ^= t + Math.imul(t ^ t >>> 7, t | 61);
                return ((t ^ t >>> 14) >>> 0) / 4294967296;
            };
        }

        const game = {
            size: { rows: ROWS, cols: COLS },
            spawn: { r: 1, c: 1 },
            exit: { r: ROWS - 2, c: COLS - 2 },
            elapsed: 0,
            maze: [],
            bots: [],
            prevPositions: [], // Used for interpolation between logic ticks
            currentTick: 0,
            lastFinishTick: 0,

            init(seed) {
                const rand = mulberry32(seed || Math.floor(Math.random() * 1000000));

                // Initialize maze with all walls true
                this.maze = Array.from({ length: ROWS }, () => 
                    Array.from({ length: COLS }, () => ({ n: true, e: true, s: true, w: true }))
                );

                // Recursive Backtracker to generate a Perfect Maze
                const visited_gen = Array.from({ length: ROWS }, () => Array(COLS).fill(false));
                const genStack = [[1, 1]];
                visited_gen[1][1] = true;

                while (genStack.length > 0) {
                    const [r, c] = genStack[genStack.length - 1];
                    const dirs = [
                        { dr: -1, dc: 0, dir: 'n', opp: 's' },
                        { dr: 0, dc: 1, dir: 'e', opp: 'w' },
                        { dr: 1, dc: 0, dir: 's', opp: 'n' },
                        { dr: 0, dc: -1, dir: 'w', opp: 'e' }
                    ];
                    // Shuffle directions for randomness
                    for (let i = dirs.length - 1; i > 0; i--) {
                        const j = Math.floor(rand() * (i + 1));
                        [dirs[i], dirs[j]] = [dirs[j], dirs[i]];
                    }

                    let moved = false;
                    for (const d of dirs) {
                        const nr = r + d.dr;
                        const nc = c + d.dc;
                        if (nr >= 0 && nr < ROWS && nc >= 0 && nc < COLS && !visited_gen[nr][nc]) {
                            this.maze[r][c][d.dir] = false;
                            this.maze[nr][nc][d.opp] = false;
                            visited_gen[nr][nc] = true;
                            genStack.push([nr, nc]);
                            moved = true;
                            break;
                        }
                    }
                    if (!moved) genStack.pop();
                }

                this.spawn = { r: 1, c: 1 };
                this.exit = { r: ROWS - 2, c: COLS - 2 };

                // Initialize Bots
                this.bots = [];
                for (let i = 0; i < BOT_COUNT; i++) {
                    const dirs = ['n', 'e', 's', 'w'];
                    // Unique preference orders for each bot to ensure spread
                    const pref = [...dirs].sort(() => Math.random() - 0.5);
                    this.bots.push({
                        r: this.spawn.r,
                        c: this.spawn.c,
                        path: [[this.spawn.r, this.spawn.c]],
                        stack: [[this.spawn.r, this.spawn.c]],
                        visited: new Set([`${this.spawn.r},${this.spawn.c}`]),
                        deadEnds: [],
                        pref: pref,
                        finishTick: null,
                        renderX: this.spawn.r, // Rendering helpers
                        renderY: this.spawn.c,
                        targetX: this.spawn.r,
                        targetY: this.spawn.c,
                        progress: 0
                    });
                }

                this.elapsed = 0;
                this.currentTick = 0;
                this.lastFinishTick = 0;
                this.prevPositions = this.bots.map(b => ({ r: b.r, c: b.c }));
            },

            walls(r, c) {
                return this.maze[r][c];
            },

            tick(n) {
                for (let i = 0; i < n; i++) {
                    this.currentTick++;
                    for (const bot of this.bots) {
                        if (bot.finishTick !== null) continue;

                        let moved = false;
                        // Exploration: Check neighbors in preference order
                        for (const dir of bot.pref) {
                            const dr = dir === 'n' ? -1 : dir === 's' ? 1 : 0;
                            const dc = dir === 'e' ? 1 : dir === 'w' ? -1 : 0;
                            const nr = bot.r + dr;
                            const nc = bot.c + dc;

                            // Check bounds and wall memory (local knowledge)
                            if (nr >= 0 && nr < ROWS && nc >= 0 && nc < COLS) {
                                if (!this.maze[bot.r][bot.c][dir]) {
                                    if (!bot.visited.has(`${nr},${nc}`)) {
                                        // Move forward: Learn new cell, add to path/stack
                                        bot.r = nr;
                                        bot.c = nc;
                                        bot.path.push([bot.r, bot.c]);
                                        bot.stack.push([bot.r, bot.c]);
                                        bot.visited.add(`${bot.r},${bot.c}`);
                                        moved = true;
                                        break;
                                    }
                                }
                            }
                        }

                        // Backtrack if no new passages are found (Tremaux/DFS logic)
                        if (!moved && bot.stack.length > 1) {
                            const prev = bot.stack.pop();
                            bot.r = prev[0];
                            bot.c = prev[1];
                            bot.path.push([bot.r, bot.c]); // Entering cell again (traversed twice)
                        }

                        // Check for exit arrival
                        if (bot.r === this.exit.r && bot.c === this.exit.c) {
                            bot.finishTick = this.currentTick;
                            this.lastFinishTick = Math.max(this.lastFinishTick, bot.finishTick);
                        }
                    }

                    // Freeze timer when all bots are done
                    const allFinished = this.bots.every(b => b.finishTick !== null);
                    if (!allFinished) {
                        this.elapsed = this.currentTick;
                    } else {
                        this.elapsed = this.lastFinishTick;
                    }
                }
                // Sync logical state for the renderer after synchronous ticks
                this.prevPositions = this.bots.map(b => ({ r: b.r, c: b.c }));
            },

            reset(seed) {
                this.init(seed);
            }
        };

        window.game = game;

        // --- Rendering Loop ---
        const canvas = document.getElementById('gameCanvas');
        const ctx = canvas.getContext('2d');
        let lastRenderTime = 0;

        function resize() {
            const size = Math.min(window.innerHeight * 0.7, window.innerWidth * 0.8);
            canvas.width = size;
            canvas.height = size;
        }
        window.addEventListener('resize', resize);
        resize();

        function render(time) {
            const deltaTime = time - lastRenderTime;
            lastRenderTime = time;

            const cellSize = canvas.width / COLS;

            // Clear and draw maze walls
            ctx.fillStyle = '#000';
            ctx.fillRect(0, 0, canvas.width, canvas.height);
            ctx.strokeStyle = '#444';
            ctx.lineWidth = 2;
            for (let r = 0; r < ROWS; r++) {
                for (let c = 0; c < COLS; c++) {
                    const w = game.maze[r][c];
                    if (w.n) { ctx.beginPath(); ctx.moveTo(c * cellSize, r * cellSize); ctx.lineTo((c + 1) * cellSize, r * cellSize); ctx.stroke(); }
                    if (w.e) { ctx.beginPath(); ctx.moveTo((c + 1) * cellSize, r * cellSize); ctx.lineTo((c + 1) * cellSize, (r + 1) * cellSize); ctx.stroke(); }
                    if (w.s) { ctx.beginPath(); ctx.moveTo(c * cellSize, (r + 1) * cellSize); ctx.lineTo((c + 1) * cellSize, (r + 1) * cellSize); ctx.stroke(); }
                    if (w.w) { ctx.beginPath(); ctx.moveTo(c * cellSize, r * cellSize); ctx.lineTo(c * cellSize, (r + 1) * cellSize); ctx.stroke(); }
                }
            }

            // Draw Exit point
            ctx.fillStyle = '#f00';
            ctx.fillRect(game.exit.c * cellSize + 2, game.exit.r * cellSize + 2, cellSize - 4, cellSize - 4);

            let completedCount = 0;
            game.bots.forEach((bot, i) => {
                if (bot.finishTick !== null) completedCount++;

                const currentPos = bot.path[bot.path.length - 1];

                // Update target if logic changed the cell position
                if (bot.targetX !== currentPos[0] || bot.targetY !== currentPos[1]) {
                    bot.targetX = currentPos[0];
                    bot.targetY = currentPos[1];
                    bot.progress = 0;
                }

                // Interpolate visually (speed constant: ~100ms to transition one cell)
                bot.progress += deltaTime / 100;
                if (bot.progress >= 1) {
                    bot.renderX = bot.targetX;
                    bot.renderY = bot.targetY;
                    bot.progress = 0;
                }

                const x = bot.renderX * cellSize + cellSize / 2;
                const y = bot.renderY * cellSize + cellSize / 2;

                ctx.fillStyle = `hsl(${i * 137.5 % 360}, 80%, 60%)`;
                ctx.beginPath();
                ctx.arc(x, y, cellSize / 4, 0, Math.PI * 2);
                ctx.fill();
            });

            document.getElementById('completed').innerText = completedCount;
            document.getElementById('timer').innerText = game.elapsed;

            requestAnimationFrame(render);
        }

        // Initialization
        game.init();
        requestAnimationFrame(render);

        document.getElementById('reset').addEventListener('click', () => {
            game.init();
        });
    </script>
</body>
</html>
